program:
// Domed citadel: fluted terrace, 32-bay two-storey drum with pointed arches, portico + grand stair,
// ribbed geodesic dome with raised cell panels. Z-up, mm. Front/entrance faces -y.
dome_freq = 6;                 // geodesic frequency of the dome (6 -> ~360 cells above the equator)
N = 32;  ENTRY = 24;  STEP = 360 / N;     // bay count; entry bay index (24 -> 270 deg = -y)
DC = 80; DR = 86;              // dome centre height, dome radius

// ---------- helpers ----------
module blk(c, z0, w, d, h, yaw = 0, top = 1)       // block: w along x, d along y, then yaw (deg)
  translate([c[0], c[1], z0]) rotate(yaw) linear_extrude(height = h, scale = top) square([w, d], center = true);
module cyl(r, z0, h, n = 64) translate([0,0,z0]) cylinder(r = r, h = h, $fn = n);
module rad(th, x) rotate(th) translate([x, 0, 0]) children();              // place children at radius x, angle th
// prism along the radial axis from r1 to r2; polygon u = tangent, v = up; tapers so adjacent bays meet
module radial(th, r1, r2, z0, pts) rotate([0,0,th]) translate([r1,0,z0]) rotate([90,0,90])
  linear_extrude(height = r2 - r1, scale = [r2 / r1, 1]) polygon(pts);

// pointed (equilateral) arch opening cut into a wall panel: width w, half-opening a, spring height s, panel height H
function arch(w, a, s, H) = let(L = [for (k = [1:4]) let(g = 180 - k*15) [a + 2*a*cos(g), s + 2*a*sin(g)]])
  concat([[-w/2,0],[-a,0],[-a,s]], L, [for (i = [2:-1:0]) [-L[i][0], L[i][1]]], [[a,s],[a,0],[w/2,0],[w/2,H],[-w/2,H]]);
// panel with slit windows [x, half-width, height] cut up from the bottom edge
function slits(w, H, S) = concat([[-w/2,0]], [for (q = S) each [[q[0]-q[1],0],[q[0]-q[1],q[2]],[q[0],q[2]+2.2],[q[0]+q[1],q[2]],[q[0]+q[1],0]]], [[w/2,0],[w/2,H],[-w/2,H]]);

// ---------- terrace + plinth ----------
module terrace() {
  cyl(150, 0, 14);  cyl(153, 14, 2.5);  cyl(134, 16.5, 0.8);
  for (i = [0:63]) rad(i * 360 / 64, 151.2) blk([0,0], 0, 2.4, 3.4, 14);                 // wall ribs (fluting)
}
module terrace_trim() {
  for (i = [0:55]) { a = i * 360 / 56; if (abs(a - 270) > 7.5) rad(a, 146) { blk([0,0], 16.5, 1.8, 1.8, 7); blk([0,0], 23.5, 2.8, 2.8, 1.1); } }   // rim posts, gap at the stair
  for (i = [0:7]) { a = 22.5 + i * 45; if (abs(a - 270) > 30) rad(a, 126) { blk([0,0], 16.5, 5, 5, 3); blk([0,0], 35.5, 3.6, 3.6, 6, 0, 0.01); } }  // pylon base + pyramid tip
  cyl(96, 22, 3);
}
module pylons() { for (i = [0:7]) { a = 22.5 + i * 45; if (abs(a - 270) > 30) rad(a, 126) blk([0,0], 19.5, 3.6, 3.6, 16); } }
module plaza() { cyl(114, 16.5, 1.6); cyl(100, 16.5, 5.5);
  for (i = [0:23]) blk([0, -202 + 4*i + 2], 0, 40, 4, (i + 1) * 25 / 24); }          // grand stair treads

// ---------- drum ----------
w1 = 2 * 82 * tan(180 / N) + 0.3;
module interior() cyl(79, 25, 45, 48);                                                  // dark wall seen through the arches
module walls() {
  for (k = [0:N-1]) { th = k * STEP;  e = (k == ENTRY);
    radial(th, 82, 90, 25,   arch(w1, e ? 6.3 : 5.1, e ? 12 : 14, 27));                // lower storey: pointed-arch bays
    radial(th, 82, 90, 54.5, slits(w1, 13.5, e ? [[-4.5,1.1,9],[4.5,1.1,9]] : [[-3.6,1,9],[3.6,1,9]]));   // upper storey: slit windows
  }
  cyl(90, 73, 7);  cyl(89.6, 80, 11.4);                                                 // attic + dome tambour
  blk([0,-99], 52, 40, 11.5, 3.5);                                                      // portico entablature
  translate([0,-93,56.7]) rotate([90,0,0]) linear_extrude(height = 12) polygon([[-22,0],[22,0],[0,8.5]]);   // pediment
  for (i = [0:23]) for (x = [-22.5, 22.5]) blk([x, -202 + 4*i + 2], 0, 5, 4, (i + 1) * 25 / 24 + 5);       // stair cheek walls
  for (x = [-38, 38]) blk([x, -210], 0, 5, 5, 15);                                      // gate posts
}
module pilasters() {
  for (k = [0:N-1]) rad(k * STEP + STEP / 2, 91.9) translate([0,0,27.2]) cylinder(r = 1.75, h = 38.8, $fn = 8);
  for (i = [0:15]) rad(i * 22.5, 92.4) blk([0,0], 73, 5, 6, 20);                         // buttress piers
  for (x = [-14, -5, 5, 14]) translate([x, -101.5, 27]) cylinder(r = 2.5, h = 23, $fn = 12);   // portico columns
  for (x = [-22.5, 22.5]) { blk([x,-205], 0, 7, 7, 13);  blk([x,-107], 25, 7, 7, 13); }        // stair newels
}
module trim() {
  for (k = [0:N-1]) rad(k * STEP + STEP / 2, 91.9) { blk([0,0], 25, 4.4, 4.4, 2.2); blk([0,0], 66, 4.8, 4.8, 2.2); }   // pilaster bases + capitals
  cyl(91.6, 52, 2.5);                                                                    // string course
  for (i = [0:63]) rad((i + 0.5) * 360 / 64, 94.6) blk([0,0], 65.2, 1.8, 2.2, 3);        // dentils
  cyl(93.5, 68.2, 1.6);  cyl(96, 69.8, 1.6);  cyl(97.5, 71.4, 1.6);                      // stepped cornice
  cyl(91.4, 91.4, 1.8);  cyl(89.4, 93.2, 1.2);                                           // tambour cap rings
  for (i = [0:15]) rad(i * 22.5, 92.4) blk([0,0], 93, 6, 7, 1.6);                         // pier caps
  blk([0,-99], 22, 44, 14, 3);  blk([0,-99], 55.5, 42, 13, 1.2);                          // porch floor + roof slab
  for (x = [-14, -5, 5, 14]) { blk([x,-101.5], 25, 6.2, 6.2, 2); blk([x,-101.5], 50, 6.4, 6.4, 2); }
  for (x = [-22.5, 22.5]) { blk([x,-205], 13, 8, 8, 2); blk([x,-107], 38, 8, 8, 2); }
  for (x = [-38, 38]) blk([x,-210], 15, 6, 6, 1.5);
}
module glow()   { rad(ENTRY * STEP, 80.5) blk([0,0], 25, 5, 1.2, 22);                    // portal glow slit
                  for (x = [-38, 38]) blk([x,-210], 16.5, 3, 3, 3);
                  translate([0,0,DC + DR - 1]) rotate_extrude($fn = 8) polygon([[0,0],[3.6,0],[2,5.6],[0.15,16],[0,16]]); }   // gold finial
module lights() { for (k = [0:N-1]) if (k != ENTRY && k % 3 == 0) rad(k * STEP, 80.6) blk([0,0], 27, 4, 1, 13); }

// ---------- dome: geodesic cells, each an inset raised panel ----------
phi = (1 + sqrt(5)) / 2;
function nrm(v) = v / norm(v);
IV = [for (p = [[-1,phi,0],[1,phi,0],[-1,-phi,0],[1,-phi,0],[0,-1,phi],[0,1,phi],[0,-1,-phi],[0,1,-phi],[phi,0,-1],[phi,0,1],[-phi,0,-1],[-phi,0,1]]) nrm(p)];
IF = [[0,11,5],[0,5,1],[0,1,7],[0,7,10],[0,10,11],[1,5,9],[5,11,4],[11,10,2],[10,7,6],[7,1,8],[3,9,4],[3,4,2],[3,2,6],[3,6,8],[3,8,9],[4,9,5],[2,4,11],[6,2,10],[8,6,7],[9,8,1]];
function gp(A,B,C,f,i,j) = nrm(A + (B-A)*i/f + (C-A)*j/f);
function tris(f) = [for (fc = IF) let(A = IV[fc[0]], B = IV[fc[1]], C = IV[fc[2]])
  each [for (i = [0:f-1]) for (j = [0:f-1-i]) each concat(
    [[gp(A,B,C,f,i,j), gp(A,B,C,f,i+1,j), gp(A,B,C,f,i,j+1)]],
    (i + j <= f-2) ? [[gp(A,B,C,f,i+1,j), gp(A,B,C,f,i+1,j+1), gp(A,B,C,f,i,j+1)]] : [])]];
TR = tris(dome_freq);
module cell(t, ro, ri, s) {
  g = (t[0] + t[1] + t[2]) / 3 * ro;  o = [for (k = [0:2]) g + (t[k]*ro - g) * s];
  polyhedron(points = concat(o, [for (k = [0:2]) t[k]*ri]), faces = [[0,2,1],[3,4,5],[0,1,4,3],[1,2,5,4],[2,0,3,5]]);
}
function above(i) = (TR[i][0][2] + TR[i][1][2] + TR[i][2][2]) / 3 >= -0.03;           // keep the upper hemisphere
function cls(i) = (i % 7 == 0) ? 2 : (i % 5 == 0) ? 1 : 0;                              // 0 peach, 1 coral, 2 lavender
module dome(c) translate([0,0,DC]) for (i = [0:len(TR)-1]) if (above(i) && cls(i) == c) cell(TR[i], DR + 1.1, DR - 3, 0.72);

function rp(a, j) = let(f = j / 12 * 86, Rr = DR + 2.2) [Rr*cos(f)*cos(a), Rr*cos(f)*sin(a), DC + Rr*sin(f)];
module ribs() for (i = [0:15]) for (j = [0:11])
  hull() { translate(rp(i * 22.5, j)) sphere(r = 1.1, $fn = 6);  translate(rp(i * 22.5, j + 1)) sphere(r = 1.1, $fn = 6); }
